import { z } from 'zod'

// data/index.json — landing-page aggregate, generated by
// tools/build-places-index.mjs from the published artifacts. Derived data only.
const Thread = z.object({
  excerpt: z.string(),
  teller: z.string(),
  channel: z.string(),
  signal: z.string(),
  intervention: z.string().nullable(),
})

const PlaceEntry = z.object({
  id: z.string(),
  name: z.string(),
  data: z.enum(['real', 'dummy']),
  geo: z.object({ lat: z.number(), lon: z.number() }).nullable(),
  counts: z.object({
    stories: z.number(),
    claims: z.number(),
    signals: z.number(),
    interventions: z.number(),
  }),
  thread: Thread.nullable(),
})

export const PlacesIndexSchema = z.object({
  generated: z.string(),
  places: z.array(PlaceEntry),
})
export type PlacesIndex = z.infer<typeof PlacesIndexSchema>

export async function loadIndex(): Promise<PlacesIndex> {
  const res = await fetch(`${import.meta.env.BASE_URL}data/index.json`, {
    signal: AbortSignal.timeout(15_000),
  })
  if (!res.ok) throw new Error(`Could not load index file (${res.status})`)
  return PlacesIndexSchema.parse(await res.json())
}
